import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.GUIDataPickItem{ItemName: "minecraft:diamond_sword", ItemEffects: "Sharpness V", HotBarSlot: 300}
SWORD = bytes.fromhex("176d696e6563726166743a6469616d6f6e645f73776f72640b53686172706e65737320562c010000")

# generated by gophertunnel b8bd735:
# packet.GUIDataPickItem{HotBarSlot: -1}
NEGATIVE_SLOT = bytes.fromhex("0000ffffffff")

GOLDENS = [
    pytest.param(
        v2225.GuiDataPickItemPacket(item_name="minecraft:diamond_sword", item_effect_name="Sharpness V", slot=300),
        SWORD,
        id="sword",
    ),
    pytest.param(v2225.GuiDataPickItemPacket(slot=-1), NEGATIVE_SLOT, id="empty-strings-negative-slot"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_gui_data_pick_item_is_packet_54(version):
    assert version.packets[54] is version.GuiDataPickItemPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_gui_data_pick_item_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_gui_data_pick_item_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
